// Turns the committed JSON Schema (from harabhara/contracts.py) into TypeScript types.
import { readFile, writeFile } from "node:fs/promises";
import { compile } from "json-schema-to-typescript";

const schema = JSON.parse(await readFile("src/api/contracts.schema.json", "utf8"));
const ts = await compile(schema, "Contracts", {
  additionalProperties: false,
  bannerComment:
    "/* GENERATED by scripts/gen-types.mjs from harabhara/contracts.py. Do not edit. */",
  style: { singleQuote: false },
});
await writeFile("src/api/contracts.d.ts", ts);
